package com.example.splitstory;
import android.app.Activity;import android.content.*;import android.net.Uri;import android.provider.DocumentsContract;import android.security.keystore.*;import org.json.*;import java.io.*;import java.math.BigInteger;import java.nio.charset.StandardCharsets;import java.security.*;import java.security.cert.X509Certificate;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;import javax.security.auth.x500.X500Principal;
final class GameApkExporter {
final MainActivity activity;final AtomicBoolean busy=new AtomicBoolean();volatile File pending;volatile File folder;
GameApkExporter(MainActivity a){activity=a;}
// Pictures and sounds arrive one at a time before start(), so no single bridge string holds them all.
static final java.util.regex.Pattern MEDIA=java.util.regex.Pattern.compile("[a-f0-9]{32}\\.(webp|png|jpg|ogg|mp3|wav|m4a|aac|flac|webm)");static final long MEDIA_LIMIT=300000000L;
File mediaDir(){return new File(activity.getCacheDir(),"game-apk-media");}
void deleteMedia(){File[] fs=mediaDir().listFiles();if(fs!=null)for(File f:fs)f.delete();}
synchronized boolean clearMedia(){if(busy.get())return false;deleteMedia();return true;}
synchronized boolean stageMedia(String name,String base64){if(busy.get()||name==null||base64==null||!MEDIA.matcher(name).matches())return false;try{File dir=mediaDir();dir.mkdirs();byte[] bytes=android.util.Base64.decode(base64,android.util.Base64.DEFAULT);if(bytes.length==0||bytes.length>40000000)return false;long total=bytes.length;File[] fs=dir.listFiles();if(fs!=null)for(File f:fs)if(!f.getName().equals(name))total+=f.length();if(total>MEDIA_LIMIT)return false;try(FileOutputStream out=new FileOutputStream(new File(dir,name))){out.write(bytes);}return true;}catch(Exception e){return false;}}
boolean start(String data,String gameId,String title){if(data==null||data.length()>50000000||activity.exportBytes!=null||!busy.compareAndSet(false,true))return false;
 new Thread(()->{try{
  JSONObject pack=new JSONObject(data);if(!"event-vault-file".equals(pack.optString("format"))||!gameId.matches("[a-zA-Z0-9_-]{1,100}")||title==null||title.trim().isEmpty()||title.length()>100)throw new IOException("게임 내보내기 형식을 확인하세요.");
  byte[] bytes=data.getBytes(StandardCharsets.UTF_8);if(bytes.length>50000000)throw new IOException("게임 데이터가 50MB를 넘었습니다.");
  File cache=new File(activity.getCacheDir(),"game-apk-export");cache.mkdirs();folder=java.nio.file.Files.createTempDirectory(cache.toPath(),"build-").toFile();File payload=new File(folder,"game.json"),shell=new File(folder,"shell.apk"),output=new File(folder,"game.apk");try(FileOutputStream out=new FileOutputStream(payload)){out.write(bytes);}
  try(InputStream in=activity.getAssets().open("player-shell.apk");FileOutputStream out=new FileOutputStream(shell)){copy(in,out);}
  CreatorKeys signing=new CreatorSigning(activity).get(gameId,true);PrivateKey key=signing.key;X509Certificate cert=signing.cert;String pkg=ApkExportEngine.packageName(gameId,cert);SharedPreferences prefs=activity.getSharedPreferences("game-apk-versions",0);int last=prefs.getInt(pkg,0);if(last==Integer.MAX_VALUE)throw new IOException("APK 버전 한도");int version=last+1;
  if(!prefs.edit().putInt(pkg,version).commit())throw new IOException("APK 버전 정보를 저장하지 못했습니다.");
  File icon=null;JSONObject body=new JSONObject(pack.getString("body"));String image=body.optString("exportIcon","");if(!image.isEmpty()){if(!image.startsWith("data:image/png;base64,")||image.length()>2600000)throw new IOException("아이콘 형식");byte[] png=android.util.Base64.decode(image.substring(22),android.util.Base64.DEFAULT);android.graphics.Bitmap bitmap=android.graphics.BitmapFactory.decodeByteArray(png,0,png.length);if(bitmap==null||bitmap.getWidth()!=432||bitmap.getHeight()!=432)throw new IOException("아이콘 크기");bitmap.recycle();icon=new File(folder,"icon.png");try(FileOutputStream out=new FileOutputStream(icon)){out.write(png);}
   // The icon lives in the APK resources; the player never reads it from game.json.
   body.remove("exportIcon");pack.put("body",body.toString());try(FileOutputStream out=new FileOutputStream(payload)){out.write(pack.toString().getBytes(StandardCharsets.UTF_8));}}
  Map<String,File> media=new LinkedHashMap<>();for(String kind:new String[]{"images","sounds"}){JSONArray list=pack.optJSONArray(kind);if(list==null)continue;for(int i=0;i<list.length();i++){String v=list.getString(i);if(!v.startsWith("media/"))continue;String name=v.substring(6);File f=new File(mediaDir(),name);if(!MEDIA.matcher(name).matches()||!f.isFile())throw new IOException("그림·소리 파일이 빠졌습니다. 다시 내보내 주세요.");media.put("assets/media/"+name,f);}}
  Set<String> fonts=null;JSONArray fontList=pack.optJSONArray("exportFonts");if(fontList!=null){fonts=new HashSet<>();for(int i=0;i<fontList.length();i++)fonts.add(fontList.getString(i));}
  ApkExportEngine.build(shell,new File(activity.getApplicationInfo().sourceDir),payload,output,folder,pkg,title.trim(),version,key,cert,icon,media,fonts);
  com.android.apksig.ApkVerifier.Result verified=new com.android.apksig.ApkVerifier.Builder(output).setMinCheckedPlatformVersion(26).build().verify();if(!verified.isVerified())throw new IOException("생성한 APK 서명을 확인하지 못했습니다.");
  pending=output;String filename=title.trim().replaceAll("[\\\\/:*?\"<>|\\p{Cntrl}]","_");if(filename.codePointCount(0,filename.length())>60)filename=filename.substring(0,filename.offsetByCodePoints(0,60));final String saveName=filename+"-v"+version+".apk";
  activity.runOnUiThread(()->{if(activity.isFinishing()||activity.isDestroyed()){cleanup();return;}Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/vnd.android.package-archive");i.putExtra(Intent.EXTRA_TITLE,saveName);try{activity.startActivityForResult(i,3);}catch(Exception e){fail("APK를 저장할 파일 선택기를 열지 못했습니다.");}});
 }catch(Throwable e){fail("APK 생성 실패 · "+(e.getMessage()==null?e.getClass().getSimpleName():e.getMessage()));}},"GameApkExport").start();return true;}
void finish(int result,Intent data){final File file=pending;final long size=file==null?0:file.length();if(result!=Activity.RESULT_OK||data==null||data.getData()==null||file==null){notifyResult(false,"APK 저장을 취소했습니다.");cleanup();return;}final Uri uri=data.getData();new Thread(()->{boolean ok=false;try(InputStream in=new FileInputStream(file);OutputStream out=activity.getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException("저장 위치를 열지 못했습니다.");copy(in,out);out.flush();ok=true;}catch(Exception e){try{DocumentsContract.deleteDocument(activity.getContentResolver(),uri);}catch(Exception ignored){}}finally{cleanup();}notifyResult(ok,ok?"게임 APK("+String.format(Locale.ROOT,"%.1f",size/1048576.0)+"MB)를 저장했습니다. 이 파일을 공유하면 됩니다.":"APK 파일 저장에 실패했습니다. 다시 내보내 주세요.");},"GameApkSave").start();}
void fail(String s){cleanup();notifyResult(false,s);}
void notifyResult(boolean ok,String s){activity.runOnUiThread(()->{if(!activity.isFinishing()&&!activity.isDestroyed())activity.web.evaluateJavascript("window.onApkExportResult && window.onApkExportResult("+ok+","+JSONObject.quote(s)+")",null);});}
void cleanup(){pending=null;File dir=folder;folder=null;if(dir!=null){File[] fs=dir.listFiles();if(fs!=null)for(File f:fs)f.delete();dir.delete();}deleteMedia();busy.set(false);}
static void copy(InputStream in,OutputStream out)throws IOException{byte[] buf=new byte[32768];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);}
}
